from typing import List


def merge_intervals(intervals: List[List[int]]) -> List[List[int]]:
    """Merge overlapping integer intervals."""
    if not intervals:
        return []

    sorted = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]

    for i in range(1, len(sorted)):
        if merged[-1][1] >= sorted[i][0]:
            merged[-1][1] = max(merged[-1][1], sorted[i][1])
        else:
            merged.append(sorted[i])

    return merged


if __name__ == "__main__":
    assert merge_intervals([[1, 3], [2, 4], [5, 8]]) == [[1, 4], [5, 8]]
    assert merge_intervals([[1, 5], [6, 7], [8, 9]]) == [[1, 9]]
    assert merge_intervals([[1, 2], [3, 4], [5, 6]]) == [[1, 2], [3, 4], [5, 6]]
```

